func generatedRunnerLedgerRecoveryAdmissionAction(disposition runnerLedgerPreflightDisposition, state RecoveryState, action RecoveryAction) (runnerLedgerRecoveryAction, bool) {
	switch string(disposition) + "\x00" + string(state) + "\x00" + string(action) {
	case "empty_brand_new\u0000brand_new_inherited\u0000begin_next_attempt":
		return runnerLedgerRecoveryAction("prepare_recovery_execution"), true
	case "partial_retry_or_recovery\u0000brand_new_inherited\u0000begin_first_attempt":
		return runnerLedgerRecoveryAction("prepare_recovery_execution"), true
	case "partial_retry_or_recovery\u0000brand_new_inherited\u0000begin_next_attempt":
		return runnerLedgerRecoveryAction("prepare_recovery_execution"), true
	case "partial_retry_or_recovery\u0000dangling_statement_intent\u0000append_aborted_retryable":
		return runnerLedgerRecoveryAction("append_abort_terminal"), true
	case "partial_retry_or_recovery\u0000dangling_statement_intent\u0000append_aborted_terminal":
		return runnerLedgerRecoveryAction("append_abort_terminal"), true
	case "partial_retry_or_recovery\u0000dangling_intermediate\u0000append_aborted_retryable":
		return runnerLedgerRecoveryAction("append_abort_terminal"), true
	case "partial_retry_or_recovery\u0000dangling_intermediate\u0000append_aborted_terminal":
		return runnerLedgerRecoveryAction("append_abort_terminal"), true
	case "partial_retry_or_recovery\u0000dangling_commit_intent\u0000reconcile_commit":
		return runnerLedgerRecoveryAction("append_commit_observation_terminal"), true
	case "partial_retry_or_recovery\u0000ambiguous_unresolved\u0000reconcile_commit":
		return runnerLedgerRecoveryAction("append_ambiguous_resolution"), true
	case "partial_retry_or_recovery\u0000terminal\u0000begin_next_attempt":
		return runnerLedgerRecoveryAction("prepare_retry_handoff"), true
	case "partial_retry_or_recovery\u0000terminal\u0000return_failure":
		return runnerLedgerRecoveryAction("return_typed_failure"), true
	case "partial_retry_or_recovery\u0000divergent\u0000return_failure":
		return runnerLedgerRecoveryAction("return_typed_failure"), true
	default:
		return "", false
	}
}

func generatedRunnerLedgerRecoveryProfileAllows(profileID string, disposition runnerLedgerPreflightDisposition, state RecoveryState, action RecoveryAction) bool {
	for i := range generatedRunnerLedgerRecoveryProfiles {
		profile := &generatedRunnerLedgerRecoveryProfiles[i]
		if profile.profileID != profileID {
			continue
		}
		for j := uint8(0); j < profile.pairCount; j++ {
			pair := profile.pairs[j]
			if pair.disposition == disposition && pair.state == state && pair.action == action {
				return true
			}
		}
		return false
	}
	return false
}

